mapper.select:
select count(1)
from sys_session
where uid = #{uid,jdbcType=INTEGER}
 and create_time >= #{today,jdbcType=DATE} 
 and create_time < DATE_ADD(#{today,jdbcType=DATE}, INTERVAL 1 DAY)

mapper.insert:
insert into sys_session (session_id, uid, max_inactive_interval,
expire_time, create_time, last_access_time, data
)
values (#{sessionId,jdbcType=VARCHAR}, #{uid,jdbcType=INTEGER}, #{maxInactiveInterval,jdbcType=INTEGER},
#{expireTime,jdbcType=TIMESTAMP}, #{createTime,jdbcType=TIMESTAMP}, #{lastAccessTime,jdbcType=TIMESTAMP},
#{data,jdbcType=LONGVARCHAR}
)
